// A compact reconstruction of the inner team-member walk used by Player's
// object iterator.  The iterator node uses MSVC's virtual-inheritance member
// pointer adjustment; spelling that representation explicitly preserves the
// retail compiler's one-time setup outside the loop.

class Object;

typedef void (__cdecl *ObjectIterateFunc)(Object *, void *);
typedef int (__cdecl *BfmeCheckedObjectIterateFunc)(Object *, void *);

#pragma pointers_to_members(full_generality, virtual_inheritance)

class BfmeInnerNode;

class BfmeInnerNodeBase
{
public:
	BfmeInnerNode *bfmeNext(void);
};

class BfmeInnerNodeHead
{
private:
	unsigned char m_bfmeHead[0x68];
};

class BfmeInnerNode : public BfmeInnerNodeHead, virtual public BfmeInnerNodeBase
{
};

class BfmeInnerIterable
{
public:
	int bfmeVisit(ObjectIterateFunc func, void *userData);

private:
	unsigned char m_bfmeHead[0x0c];
	BfmeInnerNode *m_bfmeFirst;
};

extern "C" void j_00001140(void); // retail member-function thunk

int BfmeInnerIterable::bfmeVisit(ObjectIterateFunc func, void *userData)
{
	typedef BfmeInnerNode *(BfmeInnerNode::*NextFunction)(void);
	NextFunction next = &BfmeInnerNode::bfmeNext;

	BfmeInnerNode *node = m_bfmeFirst;
	while (node)
	{
		if (!((BfmeCheckedObjectIterateFunc)func)((Object *)node, userData))
			return 0;

		if (node)
			node = (node->*next)();
	}

	return 1;
}
